/* The reference skill file (T29 (l) slice 2, T29-P2-C86; P1 C89, P3 C116 point 2): skills/phi-schema-check-reference/
 * SKILL.md, generated by scripts/sync-reference.mjs from the evaluator's reference pack (its app/knowledge/reference:
 * regs.yaml, status.yaml, vendors.yaml).
 *
 * Who it serves: an assistant reading the rule text behind a practice gets the 45 CFR section, the status pages and
 * each vendor's own HIPAA page, each with the date Custosa last read it. This package is public, so the file carries
 * links and dates only (C89): no BAA yes or no, no condition, no status wording and no excerpt. Those are served from
 * the evaluator, dated, in a finding's reference part. The sync test (C86 red case 5) keeps the file equal to what the
 * script makes from core's files. */
import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { SKILL_FILE, readPack, renderReferenceSkill } from "../scripts/sync-reference.mjs";
import { coreSkip, requireCore } from "./core-checkout.mjs";

const SHIPPED = readFileSync(SKILL_FILE, "utf8");
// Core's pack, found through CUSTOSA_CORE_CONTRACTS (its app/contracts folder): app/knowledge is beside it.
const CORE_DIR = process.env.CUSTOSA_CORE_CONTRACTS ?? "";
const KNOWLEDGE = join(CORE_DIR, "..", "knowledge");
const FOUND = Boolean(CORE_DIR) && existsSync(join(KNOWLEDGE, "reference", "regs.yaml"));

const PACK = {
  regs: { "b-practice": { cite: "45 CFR 164.312(b)", who: "yaml", as_of: "2026-11-06", url: "https://www.ecfr.gov/b", excerpt: "EXCERPT-WORDS" },
    "a-practice": { cite: "45 CFR 164.502(a)", as_of: "2026-11-06", url: "https://www.ecfr.gov/a", excerpt: "EXCERPT-WORDS" } },
  status: { "some-rule": { what: "A proposed rule", state: "STATE-WORDS", checked_on: "2026-11-10", source: "https://www.reginfo.gov/x", also: "https://also.example/x" } },
  vendors: { "cloud-a": { baa: "yes", condition: "CONDITION-WORDS", plan: "PLAN-WORDS", setting: "SETTING-WORDS", checked_on: "2026-11-10", source: "https://cloud-a.example/hipaa" },
    "api-b": { baa: "no", condition: "CONDITION-NO", checked_on: "2026-11-09", source: "https://api-b.example/terms" } },
};

test("the shipped file is a skill: a name, a description, and one dated link per pack entry", () => {
  assert.match(SKILL_FILE, /skills\/phi-schema-check-reference\/SKILL\.md$/);
  const [, front, body] = SHIPPED.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  assert.match(front, /^name: phi-schema-check-reference$/m);
  assert.match(front, /^description: .{40,}$/m);
  const rows = body.split("\n").filter((l) => l.startsWith("| ") && !l.startsWith("| ---") && !/^\| (practice|what|service) \|/.test(l));
  assert.equal(rows.length, 30 + 4 + 10); // regs, status, vendors as of the pack's first release
  for (const r of rows) assert.match(r, /\]\(https:\/\/[^)\s]+\) \| \d{4}-\d{2}-\d{2} \|$/, r);
});

test("links and dates only: no BAA value, condition, plan, setting, status wording or excerpt reaches the file", () => {
  const out = renderReferenceSkill(PACK);
  for (const word of ["EXCERPT-WORDS", "STATE-WORDS", "CONDITION-WORDS", "CONDITION-NO", "PLAN-WORDS", "SETTING-WORDS", "also.example"]) {
    assert.ok(!out.includes(word), word);
  }
  assert.doesNotMatch(out, /\b(baa|yes|no)\b/i);
  assert.ok(out.includes("| cloud-a | [HIPAA page](https://cloud-a.example/hipaa) | 2026-11-10 |"));
  assert.ok(out.includes("| some-rule | [A proposed rule](https://www.reginfo.gov/x) | 2026-11-10 |"));
});

test("entries are sorted by key, so the file doesn't depend on the YAML's order", () => {
  const out = renderReferenceSkill(PACK);
  assert.ok(out.indexOf("| a-practice | [45 CFR 164.502(a)](https://www.ecfr.gov/a) | 2026-11-06 |") < out.indexOf("| b-practice |"));
  assert.ok(out.indexOf("| api-b |") < out.indexOf("| cloud-a |"));
  assert.equal(out, renderReferenceSkill({ regs: Object.fromEntries(Object.entries(PACK.regs).reverse()), status: PACK.status, vendors: PACK.vendors }));
});

test("an entry with no https link, no date, or a | in its text is refused, naming it", () => {
  const bad = (part, key, entry) => () => renderReferenceSkill({ ...PACK, [part]: { [key]: entry } });
  assert.throws(bad("regs", "p", { cite: "c", as_of: "2026-11-06", url: "http://www.ecfr.gov/p" }), /regs p: url is not an https link/);
  assert.throws(bad("regs", "p", { cite: "c", as_of: "", url: "https://www.ecfr.gov/p" }), /regs p: as_of is not a date/);
  assert.throws(bad("status", "s", { what: "a | b", checked_on: "2026-11-10", source: "https://x.example" }), /status s: what has a \|/);
  assert.throws(bad("vendors", "v", { checked_on: "2026-11-10" }), /vendors v: source is not an https link/);
});

test("the file equals what scripts/sync-reference.mjs makes from core's pack", { skip: coreSkip(FOUND, "no core reference pack (set CUSTOSA_CORE_CONTRACTS)") }, () => {
  requireCore("CUSTOSA_CORE_CONTRACTS", FOUND);
  assert.equal(SHIPPED, renderReferenceSkill(readPack(KNOWLEDGE)), `${SKILL_FILE} differs from core's pack: run node scripts/sync-reference.mjs ${KNOWLEDGE}`);
});
